@IsTest private class CoreRuntimeMessagingDTOMockTest {
  @IsTest static void rows() {
    Messaging.Email email = new Messaging.SingleEmailMessage();
    email.bccsender = true; email.emailpriority = 'High'; email.replyto = 'reply@example.com'; email.saveasactivity = true; email.senderdisplayname = 'Sender'; email.usesignature = false;
    System.assertEquals(true, email.bccsender); System.assertEquals('High', email.emailpriority); System.assertEquals('reply@example.com', email.replyto); System.assertEquals(true, email.saveasactivity); System.assertEquals('Sender', email.senderdisplayname); System.assertEquals(false, email.usesignature);
    Messaging.EmailAttachment attachment = new Messaging.EmailAttachment();
    attachment.contentid = 'cid'; attachment.contenttype = 'text/plain'; attachment.filename = 'file.txt';
    System.assertEquals('cid', attachment.contentid); System.assertEquals('text/plain', attachment.contenttype); System.assertEquals('file.txt', attachment.filename);
    Messaging.EmailFileAttachment fileAttachment = new Messaging.EmailFileAttachment();
    fileAttachment.contenttype = 'text/plain'; fileAttachment.filename = 'file.txt';
    System.assertEquals('text/plain', fileAttachment.contenttype); System.assertEquals('file.txt', fileAttachment.filename);
    Messaging.PushNotification push = new Messaging.PushNotification(new Map<String,Object>{'key' => 'value'});
    System.assertNotEquals(null, push);
    Messaging.SingleEmailMessage message = new Messaging.SingleEmailMessage();
    message.entityattachments = new List<String>{'015000000000001AAA'}; message.fileattachments = new List<Messaging.EmailFileAttachment>{fileAttachment};
    System.assertEquals(1, message.entityattachments.size()); System.assertEquals(1, message.fileattachments.size());
  }
}
